import{_ as a,o as n,c as i,a3 as l}from"./chunks/framework.MGD2uYU7.js";const g=JSON.parse('{"title":"SC-46 — Monitor phiên LIVE (admin)","description":"","frontmatter":{"title":"SC-46 — Monitor phiên LIVE (admin)"},"headers":[],"relativePath":"wireframes/admin/sc-46-monitor-phien-live.md","filePath":"wireframes/admin/sc-46-monitor-phien-live.md","lastUpdated":null}'),t={name:"wireframes/admin/sc-46-monitor-phien-live.md"};function e(c,s,d,p,o,h){return n(),i("div",null,[...s[0]||(s[0]=[l('<h1 id="sc-46-—-monitor-phien-đau-gia-live-admin" tabindex="-1">SC-46 — Monitor phiên đấu giá LIVE (admin) <a class="header-anchor" href="#sc-46-—-monitor-phien-đau-gia-live-admin" aria-label="Permalink to &quot;SC-46 — Monitor phiên đấu giá LIVE (admin)&quot;">​</a></h1><p><span class="wf-badge danger">ADMIN</span> <span class="wf-badge info">Route: /admin/dau-gia/[id]</span> <span class="wf-badge muted">Nguồn: docs/05 §4 · docs/06 endpoints 54–58 · docs/08 BR-AU-10/12/13/20/21 · docs/03 UC-11 MF-3</span></p><p><strong>Ai xem màn này</strong>: ADMIN vận hành đấu giá — giám sát phiên IN_PROGRESS realtime-ish (polling 5s như SC-06), can thiệp khi sự cố (kết thúc sớm), theo dõi anti-snipe extend. <strong>Mục đích</strong>: cùng dữ liệu feed như màn người mua (SC-06) nhưng thêm góc nhìn vận hành: <strong>danh sách participants, extend log, công cụ kết thúc sớm có lý do bắt buộc</strong>. Admin KHÔNG bid — chỉ giám sát. <strong>Ví dụ số dùng trong bản vẽ</strong>: phiên <code>DGA-2026-0001</code> (auc_01J9X3K8M2) — căn <code>CT2-A18.05</code> NOXH <code>HP-380</code> · khởi điểm <code>1.800.000.000 ₫</code> · bước <code>18.000.000 ₫</code> · giá hiện tại <code>1.926.000.000 ₫</code> · leader <code>TV-7F2A</code> · countdown <code>00:14:32</code> · 19 lượt giá / 7 người ACTIVE · đã extend 3 lần.</p><h2 id="_1-desktop-—-monitor-live-feed-participants-extend-log" tabindex="-1">1. Desktop — monitor LIVE (feed + participants + extend log) <a class="header-anchor" href="#_1-desktop-—-monitor-live-feed-participants-extend-log" aria-label="Permalink to &quot;1. Desktop — monitor LIVE (feed + participants + extend log)&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/admin/dau-gia/auc_01J9X3K8M2</span></div><div class="wf-body"><div class="wf-row" style="align-items:stretch;gap:0;"><div class="wf-admin-rail"><span class="brand">AnPhuc Admin</span><span class="item">Dashboard</span><span class="item">KYC</span><span class="item">Tin</span><span class="item">Dự án</span><span class="item active">Đấu giá</span><span class="item">Thanh toán</span><span class="item">Người dùng</span><span class="item">Audit</span></div><div class="wf-grow wf-col" style="padding:16px;min-width:0;gap:10px;"><div class="wf-row between middle wrap"><div class="wf-col" style="gap:2px;"><span class="wf-row middle" style="gap:8px;"><span class="wf-title lg">DGA-2026-0001 — Căn CT2-A18.05</span><span class="wf-badge danger live">IN_PROGRESS</span></span><span class="wf-small">NOXH HP-380 · 72 m² · 2 PN · 1 WC · tầng 18 · Sổ hồng · mở 09/10/2026 14:00 (GMT+7) · end hiệu lực 14:46:07 sau 3 lần extend <span class="wf-callout">1</span></span></div><div class="wf-row middle" style="gap:8px;"><span class="wf-countdown sm">00:14:32</span><span class="wf-btn danger sm">Kết thúc sớm <span class="wf-callout" style="background:#fff;color:var(--wf-danger);">8</span></span><span class="wf-btn ghost sm">Xem trang public → SC-06</span></div></div><div class="wf-grid cols-4"><div class="wf-card flat"><div class="pad wf-center"><span class="wf-small">GIÁ HIỆN TẠI</span><br><span class="wf-money lg">1.926.000.000 ₫</span><br><span class="wf-small">+126.000.000 so khởi điểm</span></div></div><div class="wf-card flat"><div class="pad wf-center"><span class="wf-small">DẪN ĐẦU</span><br><span class="wf-title">TV-7F2A</span><br><span class="wf-small">bid 14:31:07 <span class="wf-callout">2</span></span></div></div><div class="wf-card flat"><div class="pad wf-center"><span class="wf-small">LƯỢT GIÁ / NGƯỜI</span><br><span class="wf-title">19 · 7</span><br><span class="wf-small">bid hợp lệ 100%</span></div></div><div class="wf-card flat"><div class="pad wf-center"><span class="wf-small">TỔNG CỌC ĐÃ THU</span><br><span class="wf-title">630.000.000 ₫</span><br><span class="wf-small">7 × 90.000.000 ₫</span></div></div></div><div class="wf-row" style="align-items:flex-start;gap:12px;"><div class="wf-grow wf-col" style="gap:6px;min-width:0;"><div class="wf-row between middle"><span class="wf-title">Feed bid (như public — pseudonym) <span class="wf-callout">3</span></span><span class="wf-small">Polling 5 giây · X-Server-Time sync <span class="wf-callout">4</span></span></div><div class="wf-feed"><div class="wf-feed-head"><span>Người ra giá (bí danh)</span><span>Số tiền · Thời điểm (server)</span></div><div class="wf-feed-row"><span><b>TV-7F2A</b> <span class="wf-badge ok">dẫn đầu</span></span><span><span class="wf-money">1.926.000.000 ₫</span> · 14:31:07</span></div><div class="wf-feed-row system"><span>⏱ Extend #3 — phiên +60 giây (anti-snipe) · end hiệu lực 14:45:07 → 14:46:07 <span class="wf-callout">5</span></span></div><div class="wf-feed-row"><span>TV-2Q9B</span><span><span class="wf-money">1.908.000.000 ₫</span> · 14:30:41</span></div><div class="wf-feed-row system"><span>⏱ Extend #2 — phiên +60 giây · end hiệu lực 14:44:07 → 14:45:07</span></div><div class="wf-feed-row"><span>TV-7F2A</span><span><span class="wf-money">1.890.000.000 ₫</span> · 14:29:58</span></div><div class="wf-feed-row"><span>TV-K41M</span><span><span class="wf-money">1.872.000.000 ₫</span> · 14:29:12</span></div><div class="wf-feed-row"><span>TV-2Q9B</span><span><span class="wf-money">1.854.000.000 ₫</span> · 14:27:03</span></div><div class="wf-feed-row"><span>TV-88XD</span><span><span class="wf-money">1.836.000.000 ₫</span> · 14:22:47</span></div><div class="wf-feed-row"><span class="wf-small">… 12 giá trước đó — cuộn xem (cursor <code>?cursor=</code>, append-only không sửa/xóa)</span><span></span></div></div><div class="wf-row between middle"><span class="wf-small wf-muted">Không có nút bid ở màn này — admin không tham gia ra giá</span><span class="wf-small wf-muted">0 bid bị từ chối trong 5 phút qua <span class="wf-callout">6</span></span></div></div><div class="wf-col" style="width:300px;flex:none;gap:10px;"><div class="wf-card"><div class="pad wf-col" style="gap:6px;"><div class="wf-row between middle"><span class="wf-title">Participants (7 ACTIVE)</span><span class="wf-small wf-accent">mở danh tính 🔒 <span class="wf-callout">7</span></span></div><div class="wf-row between"><span>TV-7F2A <span class="wf-badge ok">dẫn đầu</span></span><span class="wf-small">5 bid · cọc 90.000.000 ₫</span></div><div class="wf-row between"><span>TV-2Q9B</span><span class="wf-small">4 bid · cọc 90.000.000 ₫</span></div><div class="wf-row between"><span>TV-K41M</span><span class="wf-small">3 bid · cọc 90.000.000 ₫</span></div><div class="wf-row between"><span>TV-88XD</span><span class="wf-small">2 bid · cọc 90.000.000 ₫</span></div><div class="wf-row between"><span>TV-3R7N</span><span class="wf-small">0 bid · cọc 90.000.000 ₫</span></div><div class="wf-row between"><span>TV-Q20L</span><span class="wf-small">0 bid · cọc 90.000.000 ₫</span></div><div class="wf-row between"><span>TV-M55P</span><span class="wf-small">0 bid · cọc 90.000.000 ₫</span></div></div></div><div class="wf-card"><div class="pad wf-col" style="gap:6px;"><span class="wf-title">Extend log — anti-snipe (3) <span class="wf-callout">5</span></span><div class="wf-row between"><span class="wf-small">#3 · 14:31:07</span><span class="wf-small">TV-7F2A · +60s → 14:46:07 · <span class="wf-trace">log_01J9ZR2</span></span></div><div class="wf-row between"><span class="wf-small">#2 · 14:30:41</span><span class="wf-small">TV-2Q9B · +60s → 14:45:07 · <span class="wf-trace">log_01J9ZQ8</span></span></div><div class="wf-row between"><span class="wf-small">#1 · 14:29:58</span><span class="wf-small">TV-7F2A · +60s → 14:44:07 · <span class="wf-trace">log_01J9ZQ1</span></span></div><span class="wf-small wf-muted">Mỗi lần extend = 1 audit AUCTION_EXTEND, không giới hạn số lần — log dài thì cuộn.</span></div></div><div class="wf-note" style="margin:0;">Kết thúc tự động khi hết giờ + 60 giây yên lặng cuối: ≥1 giá → AWARDED cho leader (tạo order, hạn 24h) · 0 giá → FAILED, tin về LISTED. <span class="wf-callout">9</span></div></div></div></div></div><div class="wf-footer"><span>AnPhucRealEstate — sàn NOXH được vận hành bởi An Phuc</span><span>Quy chế đấu giá</span><span>CSKH 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích hành vi (trace: docs/05 §4 · docs/08 BR-AU · docs/02 FR-AU-07/08)</div><ol><li><span class="num">1</span><span>Header hiện <b>end_at kế hoạch vs end hiệu lực</b> (effective_end_at — chỉ tăng, không bao giờ giảm) để admin thấy ngay phiên đã bị kéo bao xa. Countdown dùng chung cơ chế offset <code>X-Server-Time</code> như SC-06 — không tin đồng hồ máy khách. <span class="ref">BR-AU-12/21</span></span></li><li><span class="num">2</span><span>4 stat card cập nhật mỗi poll: giá hiện tại, leader, lượt giá/người, tổng cọc đã thu (tiền thật đang giữ — trách nhiệm vận hành). <span class="ref">FR-AU-05</span></span></li><li><span class="num">3</span><span><b>Feed identical public feed</b> (cùng API cursor) — admin thấy đúng những gì người mua thấy, kể cả pseudonym. Không có hành động sửa/xóa dòng nào: bid đã nhận là append-only tuyệt đối. <span class="ref">BR-AU-10</span> <span class="ref">BR-AU-20</span></span></li><li><span class="num">4</span><span><b>Polling 5 giây</b> như SC-06 (v1 không WebSocket); poll fail &gt; 15s → banner vàng &quot;Mất kết nối — thử lại&quot; (mục 4), dữ liệu cũ gắn nhãn thời điểm last-sync. <span class="ref">docs/05 §4</span></span></li><li><span class="num">5</span><span><b>Extend log + dòng system trong feed</b>: mỗi bid hợp lệ trong 60 giây cuối → effective_end_at += 60s, không giới hạn lần, mỗi lần 1 audit <code>AUCTION_EXTEND</code> (log_ id link sang SC-49). Admin monitor là nơi DUY NHẤT có bảng extend log riêng. <span class="ref">BR-AU-12</span> <span class="ref">FR-AU-07</span></span></li><li><span class="num">6</span><span>Chỉ số sức khỏe vận hành: đếm bid bị từ chối (422/429/403) trong window — tăng bất thường = dấu hiệu bug FE hoặc tấn công, mở log traceId điều tra. <span class="ref">NFR-O-01</span></span></li><li><span class="num">7</span><span><b>Danh tính mặc định ẩn như public</b> (chống lộ khi screen-share/họp). Nút &quot;mở danh tính&quot; chỉ khả thi khi có lý do vận hành, mỗi lần mở ghi audit; pseudonym ↔ user mapping chỉ dùng xử lý vi phạm (forfeit/suspend privilege). <span class="ref">BR-AU-20</span> <span class="ref">BR-ADM-01</span></span></li><li><span class="num">8</span><span><b>&quot;Kết thúc sớm&quot;</b> — hành động nguy hiểm nhất màn này, xem mục 2. Lưu ý: đây KHÔNG phải cancel (IN_PROGRESS cấm cancel — 409 <code>AUCTION_CANNOT_CANCEL</code>); kết thúc sớm vẫn tính kết cục theo BR-AU-13: leader hiện tại được AWARDED, cọc/hệ quả như kết thúc thường. <span class="ref">BR-AU-19</span> <span class="ref">docs/08 §10.2</span></span></li><li><span class="num">9</span><span>Kết thúc tự động do job 5s: điều kiện <code>now ≥ effective_end_at</code> VÀ 60 giây yên lặng cuối. Khi phiên đóng: feed khóa, badge đổi AWARDED/FAILED, overlay kết quả như SC-06 mục 5; admin thấy thêm winner (mở danh tính) + link order settlement. <span class="ref">BR-AU-13</span> <span class="ref">FR-AU-08</span></span></li></ol></div><h2 id="_2-modal-ket-thuc-som-—-danger-confirm-ly-do-bat-buoc" tabindex="-1">2. Modal &quot;Kết thúc sớm&quot; — danger confirm, lý do bắt buộc <a class="header-anchor" href="#_2-modal-ket-thuc-som-—-danger-confirm-ly-do-bat-buoc" aria-label="Permalink to &quot;2. Modal &quot;Kết thúc sớm&quot; — danger confirm, lý do bắt buộc&quot;">​</a></h2><div class="wf"><div class="wf-modal-overlay"><div class="wf-modal"><div class="head" style="color:var(--wf-danger);">Kết thúc sớm phiên DGA-2026-0001? <span class="wf-callout danger">10</span></div><div class="wf-lines" style="margin:10px 0;"><div class="wf-row between"><span class="wf-text">Giá hiện tại / Leader</span><span class="wf-money">1.926.000.000 ₫ · TV-7F2A</span></div><div class="wf-row between"><span class="wf-text">Còn lại nếu không can thiệp</span><span class="wf-countdown sm">00:14:32</span></div><div class="wf-row between"><span class="wf-text">Người đang tham gia ACTIVE</span><span class="wf-strong">7</span></div></div><div class="wf-note" style="background:var(--wf-danger-soft);border-color:var(--wf-danger);color:var(--wf-danger);"> Phiên sẽ <b>đóng ngay sau 60 giây yên lặng</b> và trao kết quả theo giá hiện tại: TV-7F2A trúng giá 1.926.000.000 ₫, order hạn 24h được tạo. 6 người còn lại <b>hoàn cọc trong 3 ngày làm việc</b>. Chỉ dùng khi có sự cố vận hành — không phải nút &quot;dừng cho tiện&quot;. <span class="wf-callout danger">11</span></div><span class="wf-small wf-strong">Lý do kết thúc sớm (bắt buộc, 5–500 ký tự — ghi audit, không sửa/xóa được) <span class="wf-callout">12</span></span><div class="wf-input filled" style="min-height:64px;align-items:flex-start;">Phát hiện 2 tài khoản cùng IP ra giá liên tiếp — nghi vấn thông đồng, dừng phiên để bảo toàn kết quả, chuyển hồ sơ CS-119<span class="caret">✎</span></div><div class="wf-row between" style="margin-top:4px;"><span class="wf-small">118/500 ký tự</span><span class="wf-small wf-muted">Người tham gia nhận thông báo kết quả + lý do rút gọn</span></div><div class="wf-row" style="margin-top:12px;"><span class="wf-btn" style="flex:1;">Quay lại</span><span class="wf-btn danger" style="flex:1;">KẾT THÚC SỚM — TRAO GIÁ HIỆN TẠI</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">10</span><span>Modal không đóng bằng click nền/ESC. Nút xác nhận danger + loading disabled khi gửi (chống double-submit). <span class="ref">docs/05 §1.3</span></span></li><li><span class="num">11</span><span>Modal nêu <b>kết cục cụ thể bằng số thật</b> trước khi bấm — ai trúng, giá bao nhiêu, cọc 6 người kia về đâu. Kết thúc sớm dùng đúng logic BR-AU-13 (≥1 bid → AWARDED leader; nếu chưa có bid nào → FAILED, tin về LISTED). <span class="ref">BR-AU-13/17</span></span></li><li><span class="num">12</span><span><b>Reason bắt buộc</b> + audit action riêng (enum bổ sung khi implement — ghi nhận đề xuất <code>AUCTION_END_EARLY</code> vào docs/07 §2.17 qua PR). Thành công → toast ok <b>&quot;Đã kết thúc sớm phiên DGA-2026-0001 — kết quả AWARDED TV-7F2A&quot;</b>, feed khóa, NTF-04 gửi người trúng + chủ nhà. <span class="ref">BR-ADM-01</span> <span class="ref">FR-NTF-04</span></span></li></ol></div><h2 id="_3-khoanh-khac-extend-—-nhung-gi-admin-thay-khi-phien-bi-keo-dai" tabindex="-1">3. Khoảnh khắc extend — những gì admin thấy khi phiên bị kéo dài <a class="header-anchor" href="#_3-khoanh-khac-extend-—-nhung-gi-admin-thay-khi-phien-bi-keo-dai" aria-label="Permalink to &quot;3. Khoảnh khắc extend — những gì admin thấy khi phiên bị kéo dài&quot;">​</a></h2><div class="wf"><div class="wf-col" style="max-width:620px;"><div class="wf-toast danger"><b>⏱ Extend #4 — phiên kéo dài thêm 60 giây</b> · giá 1.944.000.000 ₫ bởi TV-K41M lúc 14:45:31 · end hiệu lực mới 14:47:07</div><div class="wf-row middle" style="gap:16px;"><div class="wf-card flat" style="flex:1;"><div class="pad wf-center"><span class="wf-small">TRƯỚC</span><br><span class="wf-countdown sm" style="opacity:0.5;">00:00:36</span></div></div><span class="wf-title">→</span><div class="wf-card flat" style="flex:1;border-color:var(--wf-danger);border-width:2px;"><div class="pad wf-center"><span class="wf-small">SAU EXTEND</span><br><span class="wf-countdown sm">00:01:36</span></div></div></div><div class="wf-feed"><div class="wf-feed-head"><span>Feed + extend log nhận đồng thời</span><span></span></div><div class="wf-feed-row"><span>TV-K41M <span class="wf-badge ok">dẫn đầu mới</span></span><span><span class="wf-money">1.944.000.000 ₫</span> · 14:45:31</span></div><div class="wf-feed-row system"><span>⏱ Extend #4 — phiên +60 giây (anti-snipe) · audit log_01J9ZR9 → SC-49</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">13</span><span>Extend hiển thị <b>4 nơi đồng thời</b> cho admin: toast đỏ (tự ẩn 5s), countdown nhảy số, dòng system trong feed, dòng mới trong extend log (+audit id). Extend không giới hạn lần — phút cuối có thể lặp nhiều vòng, design không giả sử chỉ 1 lần; log phải scroll được. <span class="ref">BR-AU-12</span></span></li><li><span class="num">14</span><span>Admin không cần (và không thể) làm gì để &quot;phê duyệt&quot; extend — hoàn toàn tự động theo rule. Màn này chỉ để <b>giám sát + phát hiện bất thường</b> (vd extend liên tục bởi 1 pseudonym = dấu hiệu kéo giá). <span class="ref">FR-AU-07</span></span></li></ol></div><h2 id="_4-trang-thai-bien-bat-buoc-thiet-ke-đu" tabindex="-1">4. Trạng thái biên (bắt buộc thiết kế đủ) <a class="header-anchor" href="#_4-trang-thai-bien-bat-buoc-thiet-ke-đu" aria-label="Permalink to &quot;4. Trạng thái biên (bắt buộc thiết kế đủ)&quot;">​</a></h2><div class="wf"><div class="wf-grid cols-2"><div class="wf-col"><span class="wf-state-label">PUBLISHED — CHƯA BẮT ĐẦU</span><div class="wf-card"><div class="pad wf-col"><span class="wf-row middle" style="gap:8px;"><span class="wf-title">DGA-2026-0003 — CT1-B07.03</span><span class="wf-badge info">PUBLISHED</span></span><span class="wf-text">Mở lúc 12/10/2026 09:00 (GMT+7) · đóng đăng ký 11/10 09:00 · 3 ACTIVE / 2 PENDING_DEPOSIT</span><span class="wf-small">Feed trống &quot;Chưa có lượt giá&quot;; không countdown, thay bằng đồng hồ đếm-ngược-tới-giờ-mở; nút &quot;Kết thúc sớm&quot; ẩn — chỉ còn &quot;Hủy phiên (lý do)&quot; như SC-44 mục 2. Cọc manual chờ xác nhận → link nhanh sang SC-47.</span></div></div></div><div class="wf-col"><span class="wf-state-label">AWARDED / FAILED — ĐÃ KẾT THÚC (READ-ONLY)</span><div class="wf-card"><div class="pad wf-col"><span class="wf-row middle" style="gap:8px;"><span class="wf-title">DGA-2025-0118 — CT1-A08.03</span><span class="wf-badge ok">AWARDED</span></span><span class="wf-text">Kết thúc 05/10/2026 15:02 · 31 lượt giá · trúng: 1.310.000.000 ₫</span><span class="wf-small">Feed khóa + overlay kết quả như SC-06 mục 5; admin thấy winner thật tên (không pseudonym) + breakdown settlement + link order. FAILED: badge warn &quot;0 giá — tin về LISTED&quot;. Toàn màn read-only, không nút mutation nào.</span></div></div></div><div class="wf-col"><span class="wf-state-label">LOADING — SKELETON</span><div class="wf-card"><div class="pad wf-col"><div class="wf-skeleton" style="height:40px;"></div><div class="wf-grid cols-4" style="gap:8px;"><div class="wf-skeleton" style="height:56px;"></div><div class="wf-skeleton" style="height:56px;"></div><div class="wf-skeleton" style="height:56px;"></div><div class="wf-skeleton" style="height:56px;"></div></div><div class="wf-skeleton" style="height:220px;"></div><span class="wf-small">Skeleton header + 4 stat + feed 6 dòng; không hiện nút &quot;Kết thúc sớm&quot; cho tới khi biết chắc state = IN_PROGRESS.</span></div></div></div><div class="wf-col"><span class="wf-state-label">MẤT KẾT NỐI / LỖI</span><div class="wf-card"><div class="pad wf-col"><div class="wf-toast warn">⚠ Mất kết nối — dữ liệu có thể không cập nhật (last sync 14:31:07). <u>Thử lại</u></div><div class="wf-error-box" style="text-align:left;padding:12px;"><b>Không tải được dữ liệu phiên</b><br><span class="wf-small">AUCTION_NOT_FOUND → &quot;Phiên không tồn tại hoặc đã bị xóa khỏi hệ thống&quot; + link SC-44. Lỗi khác → hộp lỗi + traceId + Thử lại; countdown vẫn chạy theo offset đã hiệu chỉnh kèm dấu &quot;~&quot; (ước lượng).</span><br><span class="wf-trace">traceId: c07e2b91-aa44-4f10</span></div></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">15</span><span><b>4-state + 2 state nghiệp vụ</b>: Loading (skeleton) / Error (+traceId) / Empty (feed chưa có giá — chỉ xảy ra ở PUBLISHED hoặc IN_PROGRESS giai đoạn đầu) / Data; cộng PUBLISHED và AWARDED-FAILED là 2 chế độ hiển thị riêng của cùng route theo state. <span class="ref">docs/05 §1.4</span></span></li><li><span class="num">16</span><span>Mọi message lỗi lấy đúng bảng docs/06 §5; toast mutation luôn kèm &quot;đã ghi audit&quot;. Màn monitor KHÔNG có create/edit/delete dữ liệu bid — mutation duy nhất là &quot;Kết thúc sớm&quot; (mục 2). <span class="ref">docs/06 §5</span> <span class="ref">BR-AU-10</span></span></li></ol></div><h2 id="_5-checklist-designer-khi-dung-figma-cho-sc-46" tabindex="-1">5. Checklist designer khi dựng Figma cho SC-46 <a class="header-anchor" href="#_5-checklist-designer-khi-dung-figma-cho-sc-46" aria-label="Permalink to &quot;5. Checklist designer khi dựng Figma cho SC-46&quot;">​</a></h2><ul><li>[ ] Layout 3 khối: header (title + badge live + countdown + nút danger) / 4 stat card / feed trái + sidebar phải (participants + extend log + note kết cục)</li><li>[ ] Feed tái dùng pattern SC-06 (cùng component) — thêm dòng system extend có audit id; KHÔNG vẽ nút bid nào</li><li>[ ] Extend sequence 2 frame trước/sau (mục 3) + toast đỏ + log mới; vẽ case &quot;4+ lần extend&quot; để dev không giả sử 1 lần</li><li>[ ] Modal kết thúc sớm: số thật (leader, giá, số người), reason textarea + counter, nút danger, loading; phân biệt rõ với Cancel (chỉ DRAFT/PUBLISHED ở SC-44)</li><li>[ ] Participants: mặc định pseudonym; frame phụ &quot;mở danh tính&quot; (có lý do + audit) cho nghiệp vụ vi phạm</li><li>[ ] Đủ state: PUBLISHED / IN_PROGRESS / AWARDED-FAILED read-only / skeleton / mất kết nối / error+traceId</li><li>[ ] Responsive note: desktop-priority (màn NOC); ≤768px sidebar xếp dưới feed, countdown + nút kết thúc sớm sticky top</li><li>[ ] Không emoji icon production (⏱/⚠/🔒 là placeholder); tiền <code>1.926.000.000 ₫</code>; giờ <code>dd/MM/yyyy HH:mm</code> + GMT+7; timestamp feed dùng giờ server <code>HH:mm:ss</code></li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ cần PM duyệt trên docs/08 trước.</p></div>',18)])])}const f=a(t,[["render",e]]);export{g as __pageData,f as default};
